    inline for (.{ .{ "English", "en", "first", "first lexical sense", "cat" }, .{ "English", "en", "second", "second lexical sense", "cat" }, .{ "English", "en", "mixed", "English sense", "cat" }, .{ "French", "fr", "mixed", "French sense", "chat" } }) |row| {
