test "Amharic current-edition external category heading keeps its explicit owner" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var namespaces = try AmharicSupportCategoryFixture.namespaces(a);
    defer namespaces.deinit();
    var codes = TestLanguages.codes();
    codes.namespace_catalog = &namespaces;
    const heading = "[https://am.wiktionary.org/wiki/%E1%88%98%E1%8B%B0%E1%89%A5:%E1%8A%A5%E1%8A%95%E1%8C%8D%E1%88%8A%E1%8B%9D%E1%8A%9B እንግሊዝኛ]";
    try std.testing.expect(resolveLinkedHeading(codes, heading) == null);
    try namespaces.attachInterwikiMap("am\t1\t1\t0\t0\thttps://am.wiktionary.org/wiki/$1\nfr\t1\t0\t0\t0\thttps://fr.wiktionary.org/wiki/$1\n");
    try std.testing.expectEqualStrings("en", resolveLinkedHeading(codes, heading).?.code);
    try std.testing.expectEqualStrings("en", boundaryLanguage(codes, .{ .heading = heading, .source = "" }).?.code);
    for ([_][]const u8{
        "[https://am.wiktionary.org/wiki/መደብ:እንግሊዝኛ ፈረንሳይኛ]",
        "[https://fr.wiktionary.org/wiki/መደብ:እንግሊዝኛ እንግሊዝኛ]",
        "[https://am.wiktionary.org/wiki/እንግሊዝኛ እንግሊዝኛ]",
        "[https://am.wiktionary.org/wiki/መደብ:እንግሊዝኛ]",
        "[https://am.wiktionary.org/wiki/መደብ:እንግሊዝኛ እንግሊዝኛ] extra",
    }) |other| try std.testing.expect(resolveLinkedHeading(codes, other) == null);
    const source = "<!-- በቅድሚያ ለላ የተሰራ ቃልን በማየት አሰራሩን ይማሩ፡፡ ይህ ቀለል ያለ የቃላት ገለፃና ትርጉም ምስጫ ቅጽ ነው፡፡ በቅጹ ውስጥ በ\"<\"ና  በ\">\" መሃከል ያሉ መመሪያዎች ሊሰርዙት ይችላሉ፡፡ -->\n==[https://am.wiktionary.org/wiki/%E1%88%98%E1%8B%B0%E1%89%A5:%E1%8A%A5%E1%8A%95%E1%8C%8D%E1%88%8A%E1%8B%9D%E1%8A%9B እንግሊዝኛ]==\n=== ቋንቋ ===\n* እንግሊዝኛ<!-- የቋንቋውን ስም እዚህ ይምረጡ ከሌለ ይጻፉት፣ ኦሮምኛ፣ ፍረሳይኛ፣ ጣሊያንኛ፣ ወላይትኛ፣ ትግርኛ፣ ሩሲያኛ፣ ቻይንኛ... ወዘተ -->\n=== አባባል\\አጠራር\\አነጋገር ===\n<!-- በእንግሊዝኛው pronounciation እንደሚባለው ማለት ነው፡፡ በአማርኛ ፊደላትና ፎነቲክ ከቻሉ አባባሉን ያስቀምጡት-->\n\n=== የንግግር ክፍል ===\n==== ስም<!--  የንግግር ክፍሉን ከዚህ ይምረጡ ከሌለ ያስገቡት፣  ስም፣ ተውላጠስም፣ ግስ፣ተውሳከግስ፣ ቅጽል፣ ወዘተ --> ====\n* ገለፃ/ትርጉም\n# [[ክብድ ትዕምርት<!--ገለፃ ወይም ትርጉም እዚህ ያስገቡ-->]]\n#: <!-- ምሳሌ-->\n\n=== ተጠቃሽ መረጃዎች ===\n# [[ en:accent grave<!--የምንጭ ቋንቋ ዊክሽነሪ ተጠቃሽ ገጽን እዚህ ያስገቡ፣ ምሳሌ  -->]]\n# [[ ተጨማሪ መረጃ<!--ተጨማሪ ተጠቃሽ መረጃን እዚህ ያስገቡ -->]]\n\n[[መደብ:እንግሊዝኛ]]\n[[መደብ:አስሊ]]\n[[መደብ:ስም]]";
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/blobs", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "accent grave", source, source, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);
    try std.testing.expectEqual(@as(usize, 0), stats.fallback_pages);
    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "English"));
    defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    const record = (try index.find("accent grave")).?;
    const decoded = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
    try std.testing.expectEqualStrings("en", decoded.entry.language_code);
    try std.testing.expect(std.mem.indexOf(u8, record.payload, "ገለፃ/ትርጉም") != null);
    try std.testing.expect(std.mem.indexOf(u8, record.payload, "ክብድ ትዕምርት") != null);
}

test "Amharic external heading fallback retains the original display label" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var namespaces = try AmharicSupportCategoryFixture.namespaces(arena.allocator());
    defer namespaces.deinit();
    try namespaces.attachInterwikiMap("am\t1\t1\t0\t0\thttps://am.wiktionary.org/wiki/$1\n");
    const Local = struct {
        fn get(_: ?*const anyopaque, name: []const u8) ?[]const u8 {
            return if (std.mem.eql(u8, name, "እንግሊዝኛ")) "en" else null;
        }
    };
    const heading = "[https://am.wiktionary.org/wiki/%E1%88%98%E1%8B%B0%E1%89%A5:%E1%8A%A5%E1%8A%95%E1%8C%8D%E1%88%8A%E1%8B%9D%E1%8A%9B እንግሊዝኛ]";
    const codes: LanguageCodes = .{ .get_fn = Local.get, .namespace_catalog = &namespaces };
    const result = resolveAmExternalCategoryHeading(codes, heading).?;
    const label_start = std.mem.lastIndexOfScalar(u8, heading, ' ').? + 1;
    const label = heading[label_start .. heading.len - 1];
    try std.testing.expectEqualStrings("en", result.code);
    try std.testing.expect(result.heading.ptr == label.ptr);
    try std.testing.expectEqual(label.len, result.heading.len);
}

test "invalid nowiki Poem saved reply passes strict Writer with active child link" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const codes = TestLanguages.codes();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/blobs", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    // Exact source and authenticated metadata from run03's failing saved reply.
    const output = "==English==\n\x7fWDPOEM:1:6de7476e1f06bcb2b22fadf63003350241885381b5a12baee0348cf587b53545\x7f";
    const metadata = "{\"schema\":\"wikidict.poem-phase.v1\",\"handled\":true,\"output_sha256\":\"f41413c95346a2d3881ec4226db5f8734e8edfb56f078a759f83f7cff93e73bd\",\"display_title_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"items\":[{\"token\":\"\x7fWDPOEM:0:f273b723e2adefbc9471956fd51a33396ca639a64bf2809e8fcb0b8cae5027a8\x7f\",\"kind\":\"scope\"},{\"token\":\"\x7fWDPOEM:1:6de7476e1f06bcb2b22fadf63003350241885381b5a12baee0348cf587b53545\x7f\",\"kind\":\"literal\",\"tag\":\"poem\",\"body\":\"\x7fWDPOEM:0:f273b723e2adefbc9471956fd51a33396ca639a64bf2809e8fcb0b8cae5027a8\x7f<poem><nowiki/ >A\\n[[cat]]</nowiki></poem>\"}]}";
    try writer.addExpandedPageWithReasonsAndPoem(a, .{ .id = 0, .kind = .language }, "PoemInvalidProtectedOpener", output, "==English==\n<poem><nowiki/ >{{PhaseLines}}</nowiki></poem>", null, &.{}, metadata);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);
    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "English"));
    defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    const record = (try index.find("PoemInvalidProtectedOpener")).?;
    const decoded = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
    var visible: std.ArrayList(u8) = .empty;
    var actions: usize = 0;
    var breaks: usize = 0;
    for (decoded.entry.sections) |section| for (section.blocks) |block| for (block.spans) |span| {
        try visible.appendSlice(a, span.text);
        try visible.appendSlice(a, span.trail);
        if (span.kind == .line_break) breaks += 1;
        if (span.kind == .link) {
            actions += 1;
            try std.testing.expectEqualStrings("cat", span.target);
        }
    };
    try std.testing.expect(std.mem.indexOf(u8, visible.items, "<nowiki/ >") != null);
    try std.testing.expect(std.mem.indexOf(u8, visible.items, "</nowiki>") != null);
    try std.testing.expect(std.mem.indexOf(u8, visible.items, "WDPOEM:") == null);
    try std.testing.expectEqual(@as(usize, 1), actions);
    try std.testing.expectEqual(@as(usize, 0), breaks);
}

test "metadata-only alias tails preserve display titles and rejection accounting" {
    const a = std.testing.allocator;
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    const pa = arena.allocator();
    const root = try std.fmt.allocPrint(pa, ".zig-cache/tmp/{s}/alias-display-only", .{tmp.sub_path});
    var writer = try Writer.init(io, a, root);
    defer writer.deinit();
    const Case = struct {
        title: []const u8,
        tail: []const u8,
        display: ?[]const u8,
        formatted: bool = false,
    };
    const cases = [_]Case{
        .{ .title = "Plain", .tail = "", .display = null },
        .{ .title = "Formatted", .tail = "", .display = "''Formatted''", .formatted = true },
        .{ .title = "Rejected", .tail = "", .display = "Different" },
        .{ .title = "Body", .tail = "Retained body.", .display = "''Body''", .formatted = true },
    };
    for (cases) |case| {
        try writer.namespace_coverage.input(a, 0, "", .language, true);
        try writer.addAliasExpanded(pa, .{
            .source_namespace = 0,
            .source_kind = .language,
            .source_title = case.title,
            .source_key = case.title,
            .xml_target = "word",
            .target_title = "word",
            .target_namespace = null,
            .target_kind = null,
            .target_key = "",
            .fragment = "Part",
            .presentation = "",
        }, case.tail, case.display, .{}, &.{});
    }
    writer.stats.pages_seen = cases.len;
    const stats = try writer.finish(.{});
    try std.testing.expectEqual(@as(usize, cases.len), stats.alias_records);
    try std.testing.expectEqual(@as(usize, 0), stats.language_records);
    try std.testing.expectEqual(@as(usize, 1), stats.fallback_pages);
    const coverage = writer.namespace_coverage.rows.get(0).?;
    try std.testing.expectEqual(@as(u64, cases.len), coverage.alias_pages);
    try std.testing.expectEqual(@as(u64, cases.len - 1), coverage.expanded_pages);
    try std.testing.expectEqual(@as(u64, 1), coverage.fallback_pages);

    var mapped = try mmapPath(io, try std.fs.path.join(pa, &.{ root, "aliases.wikblb" }));
    defer mapped.deinit();
    const view = try blob_format.inspect(mapped.bytes);
    var rows = view.iterator();
    var count: usize = 0;
    while (try rows.next()) |row| {
        const alias = try blobs.alias_codec.decode(row.payload);
        try blobs.alias_codec.validateKey(row.title, alias);
        const doc = try blobs.presentation_codec.decodeAlloc(pa, alias.presentation, alias.source_title, .alias, null);
        const case = for (cases) |candidate| {
            if (std.mem.eql(u8, candidate.title, alias.source_title)) break candidate;
        } else return error.UnexpectedAlias;
        try std.testing.expectEqualStrings("word#Part", doc.entry.preamble_spans[0].target);
        if (case.tail.len == 0) try std.testing.expectEqual(@as(usize, 1), doc.entry.preamble_spans.len);
        if (case.formatted) {
            try std.testing.expectEqual(@as(usize, 1), doc.entry.display_title.len);
            try std.testing.expectEqualStrings(case.title, doc.entry.display_title[0].text);
            try std.testing.expect(doc.entry.display_title[0].italic);
        } else try std.testing.expectEqual(@as(usize, 0), doc.entry.display_title.len);
        if (case.tail.len != 0) try std.testing.expect(std.mem.indexOf(u8, alias.presentation, case.tail) != null);
        count += 1;
    }
    try std.testing.expectEqual(cases.len, count);
    const report = try std.Io.Dir.cwd().readFileAlloc(io, try std.fs.path.join(pa, &.{ root, "fallback-pages.jsonl" }), pa, .limited(64 * 1024));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, report, "\n"));
    try std.testing.expect(std.mem.indexOf(u8, report, "\"title\":\"Rejected\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, report, "display_title_rejected") != null);
}

test "page heading IDs survive actual language publication and repeated owner regrouping" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const out_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/blobs", .{tmp.sub_path});
    const codes = TestLanguages.codes();
    var writer = try Writer.init(std.testing.io, a, out_root);
    defer writer.deinit();
    writer.language_codes = codes;
    const cases = [_]struct { title: []const u8, source: []const u8, english_ids: []const []const u8 }{
        .{ .title = "French first", .source = "==French==\n===Noun===\n# French body\n==English==\n===Noun===\n# English body\n", .english_ids = &.{"Noun_2"} },
        .{ .title = "English first", .source = "==English==\n===Noun===\n# English body\n==French==\n===Noun===\n# French body\n", .english_ids = &.{"Noun"} },
        .{ .title = "Repeated English", .source = "==English==\n===Noun===\n# English first\n==French==\n===Noun===\n# French body\n==English==\n===Noun===\n# English later\n", .english_ids = &.{ "Noun", "Noun_3" } },
    };
    for (cases) |case| try writer.addExpandedPageWithReasons(a, .{ .id = 0, .kind = .language }, case.title, case.source, case.source, null, &.{});
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 6), stats.language_records);
    try std.testing.expectEqual(@as(usize, 0), stats.fallback_pages);
    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, out_root, "English"));
    defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    const metadata = try blob.languageMetadata();
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    for (cases) |case| {
        const record = (try index.find(case.title)).?;
        const decoded = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, metadata);
        var nouns: usize = 0;
        for (decoded.entry.sections) |section| if (std.mem.eql(u8, section.title, "Noun")) {
            try std.testing.expect(nouns < case.english_ids.len);
            try std.testing.expectEqualStrings(case.english_ids[nouns], section.anchor);
            nouns += 1;
        };
        try std.testing.expectEqual(case.english_ids.len, nouns);
    }
}

test "normal Writer preserves nested cell paint without promoting it to the outer cell" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const codes = TestLanguages.codes();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/painted", .{tmp.sub_path});
    var writer = try Writer.init(std.testing.io, a, root);
    defer writer.deinit();
    writer.language_codes = codes;
    const source = "==English==\n===Noun===\n<table><tr><td bgcolor=\"#aaaaaa\">\n{|\n|-\n| bgcolor=\"#ff0000\" | [[Red|red]]\n| bgcolor=\"#0000ff\" | [[Blue|blue]]\n|}\nouter [[Tail|tail]]\n</td></tr></table>\n";
    try writer.addExpandedPage(a, .{ .id = 0, .kind = .language }, "nested paint", source, source, null);
    const stats = try writer.finish(codes);
    try std.testing.expectEqual(@as(usize, 1), stats.language_records);
    var mapped = try mmapPath(std.testing.io, try languageBlobPathAlloc(a, root, "English"));
    defer mapped.deinit();
    const blob = try blob_format.inspect(mapped.bytes);
    var index = try blob.buildTrustedIndexAlloc(a);
    defer index.deinit(a);
    const record = (try index.find("nested paint")).?;
    try std.testing.expectEqualStrings(blobs.presentation_codec.cell_blocks_magic, record.payload[0..4]);
    const decoded = try blobs.presentation_codec.decodeAlloc(a, record.payload, record.title, .language, try blob.languageMetadata());
    var red = false;
    var blue = false;
    var tail = false;
    var outer_tables: usize = 0;
    var actions: usize = 0;
    for (decoded.entry.sections) |section| for (section.blocks) |block| if (block.table) |table| {
        outer_tables += 1;
        try std.testing.expectEqual(@as(usize, 1), table.rows.len);
        try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
        const outer = table.rows[0].cells[0];
        try std.testing.expectEqualStrings("#aaaaaa", outer.background.?);
        try std.testing.expect(outer.spans.len == 0 and outer.nested_table == null);
        const ordered = outer.blocks.?;
        try std.testing.expectEqual(@as(usize, 2), ordered.len);
        try std.testing.expectEqual(blobs.presentation_types.BlockKind.table, ordered[0].kind);
        try std.testing.expectEqual(blobs.presentation_types.BlockKind.paragraph, ordered[1].kind);
        const child = ordered[0].table.?;
        try std.testing.expectEqual(@as(usize, 1), child.rows.len);
        try std.testing.expectEqual(@as(usize, 2), child.rows[0].cells.len);
        const targets = [_][]const u8{ "Red", "Blue" };
        const labels = [_][]const u8{ "red", "blue" };
        const colors = [_][]const u8{ "#ff0000", "#0000ff" };
        for (child.rows[0].cells, 0..) |cell, ci| {
            try std.testing.expectEqualStrings(colors[ci], cell.background.?);
            try std.testing.expect(!cell.header and cell.colspan == 1 and cell.rowspan == 1);
            try std.testing.expect(cell.blocks == null and cell.nested_table == null);
            for (cell.spans) |span| {
                try std.testing.expect(span.background == null);
                if (span.kind == .link) {
                    try std.testing.expectEqual(ci, actions);
                    try std.testing.expectEqualStrings(targets[ci], span.target);
                    try std.testing.expectEqualStrings(labels[ci], span.text);
                    if (ci == 0) red = true else blue = true;
                    actions += 1;
                } else try std.testing.expect(span.target.len == 0);
            }
        }
        var outer_text: std.ArrayList(u8) = .empty;
        for (ordered[1].spans) |span| {
            try outer_text.appendSlice(a, span.text);
            try std.testing.expect(span.background == null);
            if (span.kind == .link) {
                try std.testing.expectEqual(@as(usize, 2), actions);
                try std.testing.expectEqualStrings("Tail", span.target);
                try std.testing.expectEqualStrings("tail", span.text);
                tail = true;
                actions += 1;
            } else try std.testing.expect(span.target.len == 0);
        }
        try std.testing.expectEqualStrings("outer tail", outer_text.items);
    };
    try std.testing.expectEqual(@as(usize, 1), outer_tables);
    try std.testing.expectEqual(@as(usize, 3), actions);
    try std.testing.expect(red and blue and tail);
}

test "captured Arabic translation table keeps language-like cell headings in the page owner" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var namespaces = try @import("namespace_registry").Registry.init(a, "# wikidict-namespace-registry-v1\n# wiki\tarwiktionary\n# dump-date\t20261001\n# content-language\tar\n" ++
        "0\t\t\tfirst-letter\t0\t1\t0\twikitext\tmain\tentries\n" ++
        "10\tقالب\tTemplate\tfirst-letter\t1\t0\t0\twikitext\tcompile_only\ttemplates\n" ++
        "14\tتصنيف\tCategory\tfirst-letter\t1\t0\t0\twikitext\tcompile_only\tcategories\n");
    defer namespaces.deinit();
    const Local = struct {
        fn get(ctx: ?*const anyopaque, value: []const u8) ?[]const u8 {
            return if (resolve(ctx, value)) |owner| owner.code else null;
        }
        fn resolve(_: ?*const anyopaque, value: []const u8) ?ResolvedLanguage {
            inline for (.{ .{ "ar", "العربية", "عربية" }, .{ "fa", "الفارسية", "فارسية" } }) |row|
                if (std.mem.eql(u8, value, row[0]) or std.mem.eql(u8, value, row[1]) or std.mem.eql(u8, value, row[2])) return .{ .code = row[0], .heading = row[1] };
            return null;
        }
    };
    const codes: LanguageCodes = .{ .get_fn = Local.get, .resolve_fn = Local.resolve, .trusted_fn = Local.resolve, .strong_fn = Local.resolve, .namespace_catalog = &namespaces };
    const raw =
        "== {{اللغة|عربية}} ==\n" ++
        "=== المعاني ===\n" ++
        "# '''الرُّمَيْثِيَّة''' اسم مؤنث لمنطقة في محافظة حولي في الكويت.\n" ++
        "#: ذهبت إلى '''الرميثية''' بالسيارة\n" ++
        "\n" ++
        "=== الأصل والاشتقاق ===\n" ++
        "* نسبة إلى نبات [[w:ar:رمث|الرمث]]، أو نسبة إلى شخص يدعى ابن رمثان\n" ++
        "\n" ++
        "=== من الجذر نفسه ===\n" ++
