                .{ .text = "ನಿದರ್ಶನ", .target = "ನಿದರ್ಶನ", .external = false },
                .{ .text = "ಎತ್ತುಗೆ", .target = "ಎತ್ತುಗೆ", .external = false },
                .{ .text = "example", .target = "example", .external = false },
